function regimeDlg(x){const d=DICT.regimes;const e=x?Object.assign({combines:'',acc:''},x):{name:'',full:'',type:'Специальный',frees:'',who:'',how:'',combines:'',art:'',acc:''};
  openModal({form:true,size:'mid',render:()=>({title:x?esc(x.full||x.name):'Новый режим',sub:'Справочник платформы · ст. 46 НК КР',body:`<div class="form">${fld('Краткое название',inp('rg-name',e.name),{req:true,id:'rg-name',hint:x?'Новое название увидят все организации, в том числе в старых записях':''})}${fld('Тип',sel('rg-type',['Общий','Специальный'],e.type),{id:'rg-type'})}
    ${fld('Полное название',inp('rg-full',e.full),{req:true,full:true,id:'rg-full'})}${fld('Освобождает от',inp('rg-frees',e.frees),{full:true,id:'rg-frees',hint:'Налоги, которые режим заменяет'})}${fld('Кто применяет',`<textarea class="inp" id="rg-who" style="min-height:56px">${esc(e.who)}</textarea>`,{full:true,id:'rg-who'})}
    ${fld('Как переходят',inp('rg-how',e.how),{full:true,id:'rg-how'})}${fld('Совмещается с',inp('rg-comb',e.combines),{full:true,id:'rg-comb',hint:'С какими режимами можно применять одновременно'})}${fld('Для бухгалтера',`<textarea class="inp" id="rg-acc" style="min-height:56px">${esc(accTxt(e))}</textarea>`,{full:true,id:'rg-acc',hint:'Что этот режим значит для работы бухгалтера: какие отчёты, на что смотреть'})}${fld('Статья НК',inp('rg-art',e.art,'placeholder="гл. 57"'),{id:'rg-art'})}${gkRuleFields('rg',e.gked,null,false,true)}</div>`,
    foot:'<button class="btn ghost" data-close>Отмена</button><button class="btn cta" id="rg-ok">Сохранить</button>',
    mount(el,m){$('#rg-ok',el).onclick=()=>{const v={name:val(el,'rg-name').trim(),full:val(el,'rg-full').trim(),type:val(el,'rg-type'),frees:val(el,'rg-frees').trim(),who:val(el,'rg-who').trim(),how:val(el,'rg-how').trim(),combines:val(el,'rg-comb').trim(),art:val(el,'rg-art').trim(),acc:val(el,'rg-acc').trim()};
      const g=gkRuleRead(el,'rg',x&&x.gked);if(![setErr(el,'rg-name',!v.name?'Введите название':d.items.some(i=>i.name===v.name&&i!==x)?'Такой режим уже есть':''),setErr(el,'rg-full',v.full?'':'Введите полное название')].every(Boolean)||g===undefined)return;
      const gch=x&&!gkRuleSame(x.gked,g);if(g)v.gked=g;
      if(x){const o=x.name;if(v.name!==o)renameDictValue('regimes',o,v.name);const ch=Object.keys(v).filter(k=>k!=='gked'&&v[k]!==(x[k]||''));if(gch)ch.push('gked');if(!g)delete x.gked;Object.assign(x,v);touch(x);const cn=ch.filter(k=>k!=='name');if(ch.length)pdLog(`${d.title}: ${o!==v.name?`«${o}» → «${v.name}»${cn.length?`; изменено ещё: ${cn.length} ${plural(cn.length,'поле','поля','полей')}`:''}`:`«${v.name}» — изменено: ${ch.length} ${plural(ch.length,'поле','поля','полей')}`}`,'regimes')}
      else{d.items.push(born(Object.assign(v,{active:true,code:nextCode('regimes','РЕЖ')})));pdLog(`${d.title}: добавлено «${v.name}»`,'regimes')}m.close();refreshAll();toast('Сохранено')}}})})}
// «Меняет сроки» словами для формы статуса
const ovRuleTxt=(id,o)=>{const t=T[id];if(!t)return '';const r=(d,a)=>ruleText(Object.assign({},t,{day:ovDay(d),after:a??t.after}));return [o.day!=null?'сдача — '+r(o.day,o.after):'',o.pay?'уплата — '+r(o.pay.day,o.pay.after):''].filter(Boolean).join('; ')};
function benefitDlg(x){const d=DICT.benefits;const e=x?Object.assign({},x,{removes:[...(x.removes||[])],adds:[...(x.adds||[])],dueOverride:structuredClone(x.dueOverride||{}),suggest:structuredClone(x.suggest||{})}):{name:'',gives:'',art:'',removes:[],adds:[],until:'',who:'all',cond:'',confirm:'',combines:'',term:'',verify:false,verifyNote:''};
  const chips=(id,arr)=>`<div class="chipsel" id="${id}">${RT.filter(t=>t.active!==false&&t.kind!=='internal'||arr.includes(t.id)).map(t=>`<button type="button" data-t="${t.id}" class="${arr.includes(t.id)?'on':''}" title="${esc(t.name)}">${esc(t.short)}</button>`).join('')}</div>`;
  openModal({form:true,size:'mid',live:true,render:m=>({title:x?esc(x.name):'Новая льгота или статус',sub:'Справочник платформы',body:`<div class="form">${fld('Название',inp('bn-name',e.name),{req:true,full:true,id:'bn-name'})}${fld('Что даёт',`<textarea class="inp" id="bn-gives" style="min-height:60px">${esc(e.gives)}</textarea>`,{req:true,full:true,id:'bn-gives',hint:'Ставки и освобождения текстом'})}
    ${fld('Кто может применять',sel('bn-who',[['all','Организации и ИП'],['org','Только организации'],['ip','Только ИП']],e.who||'all'),{id:'bn-who'})}${fld('Статья НК',inp('bn-art',e.art),{id:'bn-art'})}
    ${fld('Тип',sel('bn-kind',[['','Льгота — меняет ставки или освобождает от налога'],['status','Статус — льгот не даёт, меняет отчёты или сроки']],e.kind==='status'?'status':''),{full:true,id:'bn-kind',hint:'У статуса нет предупреждения об окончании льготы'})}
    ${fld('Условия',`<textarea class="inp" id="bn-cond" style="min-height:52px">${esc(e.cond||'')}</textarea>`,{full:true,id:'bn-cond',hint:'Что нужно, чтобы применять: регистрация, доля выручки, режим'})}${fld('Как подтверждается',`<textarea class="inp" id="bn-conf" style="min-height:44px">${esc(e.confirm||'')}</textarea>`,{full:true,id:'bn-conf'})}
    ${fld('Совмещается с',inp('bn-comb',e.combines||''),{full:true,id:'bn-comb'})}${fld('Срок действия',inp('bn-term',e.term||'','placeholder="Например: бессрочно"'),{id:'bn-term'})}${fld('Действует до',inp('bn-until',e.until,'type="date"'),{id:'bn-until',hint:'Дата окончания по кодексу, если есть: за 60 дней придёт предупреждение'})}
    ${fld('Отчёты, которые статус делает ненужными',chips('bn-rm',e.removes),{full:true,id:'bn-rm'})}${fld('Отчёты, которые статус добавляет',chips('bn-ad',e.adds),{full:true,id:'bn-ad'})}
    <div class="fld full"><label>Меняет сроки</label>${Object.entries(e.dueOverride||{}).map(([id,o])=>`<div class="row" style="gap:8px"><b>${esc(T[id]?T[id].short:id)}</b><span class="grow">${esc(ovRuleTxt(id,o))}</span><button type="button" class="linkbtn" data-ovdel="${esc(id)}">Убрать</button></div>`).join('')||'<span class="faint">Сроки не меняет</span>'}
      <div class="row" style="gap:6px;flex-wrap:wrap;margin-top:6px">${sel('bn-ovt',[['','Вид отчёта…'],...RT.filter(t=>t.active!==false&&!t.oneOff&&!perOwn(t)&&!(e.dueOverride||{})[t.id]).map(t=>[t.id,t.short])],'','aria-label="Вид отчёта"')}${sel('bn-ovd',[['','Сдача: как в каталоге'],...Array.from({length:30},(_,i)=>[String(i+1),`сдача до ${i+1}-го`]),['last','сдача до последнего дня']],'','aria-label="Срок сдачи"')}${sel('bn-ovp',[['','Уплата: как в каталоге'],...Array.from({length:30},(_,i)=>[String(i+1),`уплата до ${i+1}-го`]),['last','уплата до последнего дня']],'','aria-label="Срок уплаты"')}${sel('bn-ova',[['1','месяца после периода'],['0','месяца периода'],['2','2-го месяца после периода']],'1','aria-label="Месяц"')}<button type="button" class="btn sm" id="bn-ovadd">${ic('plus','sm')}Добавить</button></div>
      <div class="hint">У контрагента с этим статусом отчёты вида получают этот срок; вариант срока в назначении важнее. Например, «Крупный налогоплательщик»: НДС — сдача до последнего дня, уплата до 25-го</div>${x&&JSON.stringify(x.dueOverride||{})!==JSON.stringify(e.dueOverride||{})?`<div class="note warn" id="bn-due">${ic('alert')}<span>${dueNote(duePreview(()=>tmpSet(x,{dueOverride:e.dueOverride})))}</span></div>`:''}</div>
    ${fld('Ставится по УГНС',`<div class="chipsel" id="bn-ug">${DICT.ugns.items.filter(u=>u.active||((e.suggest||{}).ugns||[]).includes(u.id)).map(u=>`<button type="button" data-ug="${esc(u.id)}" class="${((e.suggest||{}).ugns||[]).includes(u.id)?'on':''}">${esc(u.short)}</button>`).join('')}</div>`,{full:true,id:'bn-ug',hint:'При таком УГНС статус отмечается у контрагента сам; при смене УГНС сам не снимается'})}
    ${gkRuleFields('bn',e.gked,e._gkRaw,true)}
    <label class="check-row full" style="grid-column:1/-1"><input type="checkbox" class="sw" id="bn-ver" ${e.verify?'checked':''}><span class="grow">Сверить<div class="hint">Значение не подтверждено кодексом или постановлением: у статуса пометка «сверить»</div></span></label>${fld('Что сверить',inp('bn-vn',e.verifyNote||''),{full:true,id:'bn-vn'})}</div>`,
    foot:'<button class="btn ghost" data-close>Отмена</button><button class="btn cta" id="bn-ok">Сохранить</button>',
    mount(el){const snap=()=>{e.name=val(el,'bn-name');e.gives=val(el,'bn-gives');e.art=val(el,'bn-art');e.until=val(el,'bn-until');e.who=val(el,'bn-who');e.cond=val(el,'bn-cond');e.confirm=val(el,'bn-conf');e.combines=val(el,'bn-comb');e.term=val(el,'bn-term');e.verify=$('#bn-ver',el).checked;e.verifyNote=val(el,'bn-vn')||null;e._gkRaw=gkRaw(el,'bn');e.kind=val(el,'bn-kind')||undefined};
      $('#bn-ovadd',el).onclick=()=>{const id=val(el,'bn-ovt'),dd=val(el,'bn-ovd'),pd=val(el,'bn-ovp'),a=+val(el,'bn-ova');if(!id||(!dd&&!pd))return toast('Выберите вид отчёта и новый срок сдачи или уплаты','alert');snap();
        const o={};if(dd){o.day=dd==='last'?'last':+dd;o.after=a}if(pd)o.pay={day:pd==='last'?'last':+pd,after:a};e.dueOverride=Object.assign({},e.dueOverride,{[id]:o});m.draw()};
      $$('[data-ovdel]',el).forEach(b=>b.onclick=()=>{snap();const o=Object.assign({},e.dueOverride);delete o[b.dataset.ovdel];e.dueOverride=o;m.draw()});
      $('#bn-ug',el).onclick=ev=>{const b=ev.target.closest('[data-ug]');if(!b)return;snap();const s=e.suggest||{};const a=s.ugns||[];const k=b.dataset.ug;e.suggest=Object.assign({},s,{ugns:a.includes(k)?a.filter(z=>z!==k):[...a,k]});m.draw()};
      [['bn-rm','removes'],['bn-ad','adds']].forEach(([id,k])=>$('#'+id,el).onclick=ev=>{const b=ev.target.closest('[data-t]');if(!b)return;snap();const t=b.dataset.t;e[k]=e[k].includes(t)?e[k].filter(z=>z!==t):[...e[k],t];m.draw()});
      $('#bn-ok',el).onclick=()=>{snap();const g=gkRuleRead(el,'bn',x&&x.gked);if(g===undefined)return;delete e._gkRaw;if(g)e.gked=g;else{delete e.gked;if(x)delete x.gked}const both=(e.adds||[]).filter(t=>(e.removes||[]).includes(t)).map(t=>T[t]?T[t].short:t);
        // Один вид отчёта не может быть и в «делает ненужными», и в «добавляет» (решение заказчика 30.10.2026, Д-9)
        if(![setErr(el,'bn-name',!e.name.trim()?'Введите название':d.items.some(i=>i.name===e.name.trim()&&i!==x)?'Такой статус уже есть':''),setErr(el,'bn-gives',e.gives.trim()?'':'Опишите, что даёт статус'),setErr(el,'bn-ad',both.length?`${both.join(', ')} — уже в списке «делает ненужными»: один вид не может быть в обоих списках`:'')].every(Boolean))return;e.name=e.name.trim();
        if(!Object.keys(e.dueOverride||{}).length)delete e.dueOverride;if(e.suggest&&!(e.suggest.ugns||[]).length)delete e.suggest.ugns;if(e.suggest&&!Object.keys(e.suggest).length)delete e.suggest;
        if(x){const o=x.name;if(o!==e.name)CPS.forEach(c=>{if(c.ben)c.ben=c.ben.map(n=>n===o?e.name:n)});const ovCh=JSON.stringify(x.dueOverride||{})!==JSON.stringify(e.dueOverride||{});const was=ovCh?CPS.filter(c=>(c.ben||[]).includes(e.name)).map(c=>[c,cpOvMap(c)]):[];
          Object.assign(x,e);if(!e.dueOverride)delete x.dueOverride;if(!e.suggest)delete x.suggest;touch(x);const nr=was.reduce((n,[c,w])=>n+cpRedue(c,w),0);pdLog(`${d.title}: ${o!==e.name?`«${o}» → «${e.name}»`:`«${e.name}» изменено`}${ovCh?`, сроки по статусу пересчитаны у ${nr} ${plural(nr,'отчёта','отчётов','отчётов')}`:''}`,'benefits');m.close();refreshAll();toast('Сохранено'+dueDone(nr));return}
        else{d.items.push(born(Object.assign(e,{active:true,code:nextCode('benefits','ЛЬГ')})));pdLog(`${d.title}: добавлено «${e.name}»`,'benefits')}m.close();refreshAll();toast('Сохранено')}}})})}
// Связь «основание ↔ виды отчётов» хранится в обоих справочниках: после правки одного второй пересчитывается
const basesFromTypes=()=>(DICT.bases?DICT.bases.items:[]).forEach(b=>b.types=RT.filter(t=>(t.basis||[]).includes(b.code)).map(t=>t.id));
const typesFromBases=()=>RT.forEach(t=>{const want=DICT.bases.items.filter(b=>(b.types||[]).includes(t.id)).map(b=>b.code);if(JSON.stringify(want)!==JSON.stringify(t.basis||[])){t.basis=want;touch(t)}});
// Основание для отчётов: виды отчётов связываются через поле «Основания» вида отчёта (basis)
function baseDlg(x){const d=DICT.bases;const e=x?{name:x.name,desc:x.desc||'',note:x.note||'',types:RT.filter(t=>(t.basis||[]).includes(x.code)).map(t=>t.id)}:{name:'',desc:'',note:'',types:[]};
  openModal({form:true,size:'mid',render:m=>({title:x?esc(x.name):'Новое основание',sub:'Справочник платформы · Основания для отчётов',body:`<div class="form">${fld('Название',inp('bs-name',e.name,'placeholder="Например: Есть наёмные сотрудники"'),{req:true,full:true,id:'bs-name'})}${fld('Описание',`<textarea class="inp" id="bs-desc" style="min-height:52px">${esc(e.desc)}</textarea>`,{full:true,id:'bs-desc',hint:'Подсказка бухгалтеру: когда отмечать основание'})}
    ${fld('Виды отчётов',`<div class="chipsel" id="bs-types">${RT.filter(t=>t.active!==false&&t.kind==='cross'||e.types.includes(t.id)).map(t=>`<button type="button" data-t="${t.id}" class="${e.types.includes(t.id)?'on':''}" title="${esc(t.name)}">${esc(t.short)}</button>`).join('')}</div>`,{full:true,id:'bs-types',hint:'Какие сквозные отчёты предлагаются, когда основание отмечено'})}
    ${fld('Примечание',inp('bs-note',e.note),{full:true,id:'bs-note'})}</div>`,
    foot:'<button class="btn ghost" data-close>Отмена</button><button class="btn cta" id="bs-ok">Сохранить</button>',
    mount(el){const snap=()=>{e.name=val(el,'bs-name');e.desc=val(el,'bs-desc');e.note=val(el,'bs-note')};
      $('#bs-types',el).onclick=ev=>{const b=ev.target.closest('[data-t]');if(!b)return;snap();const t=b.dataset.t;e.types=e.types.includes(t)?e.types.filter(z=>z!==t):[...e.types,t];m.draw()};
      $('#bs-ok',el).onclick=()=>{snap();const nm=e.name.trim();if(!setErr(el,'bs-name',!nm?'Введите название':d.items.some(i=>i.name===nm&&i!==x)?'Такое основание уже есть':''))return;
        const code=x?x.code:'b'+Date.now().toString(36),o=x?x.name:nm;const rec=x||born({code,active:true});Object.assign(rec,{name:nm,desc:e.desc,types:[...e.types]});if(e.note)rec.note=e.note;else delete rec.note;
        RT.forEach(t=>{const has=(t.basis||[]).includes(code),want=e.types.includes(t.id);if(has===want)return;t.basis=want?[...(t.basis||[]),code]:t.basis.filter(k=>k!==code);if(want&&t.group!=='basis'&&!t.basis.length)t.group='basis';touch(t)});
        if(x){touch(x);pdLog(`${d.title}: ${o!==nm?`«${o}» → «${nm}»`:`«${nm}» изменено`}`,'bases')}else{d.items.push(rec);pdLog(`${d.title}: добавлено «${nm}»`,'bases')}m.close();refreshAll();toast('Сохранено')}}})})}
const END_L={org:'Организация',ip:'ИП'},BANK_T=['Банк','Электронный кошелёк'];
// Названия полей значения справочника для истории изменений
const VD_FL={note:'пояснение',full:'полное название',short:'кратко',end:'для ЕНД',type:'тип',byPhone:'переводы по номеру телефона',contacts:'телефоны',hours:'график работы',site:'сайт',contactsNote:'«Сверить»'};
// Контакты органа: телефоны с подписью, график работы, сайт и пометка «Сверить» — откуда взяты контакты (ТЗ «Органы», решение заказчика 19.10.2026; правка в Админке — 27.10.2026)
const ctRow=(c={})=>`<tr><td><input class="inp" data-cl value="${esc(c.label||'')}" placeholder="Приёмная" aria-label="Подпись номера"></td><td><input class="inp" data-cv value="${esc(c.value||'')}" placeholder="0 (312) 54-45-29" inputmode="tel" aria-label="Номер"></td><td><button type="button" class="icon-btn sm" data-crm aria-label="Убрать телефон">${ic('x','sm')}</button></td></tr>`;
const organCtHtml=x=>`${fld('Телефоны',`<div class="tbl-wrap"><table class="mini" id="vd-ct"><thead><tr><th>Подпись</th><th>Номер</th><th></th></tr></thead><tbody>${(x&&x.contacts||[]).map(ctRow).join('')}</tbody></table></div><button type="button" class="btn sm" id="vd-cadd" style="margin-top:6px">${ic('plus','sm')}Добавить телефон</button>`,{full:true,id:'vd-ct',hint:'Необязательно. В справочниках организации номер нажимается для звонка'})}${fld('График работы',inp('vd-hours',x&&x.hours||'','placeholder="Пн–Пт 9:00–18:00, перерыв 12:30–13:30"'),{full:true,id:'vd-hours'})}${fld('Сайт',inp('vd-site',x&&x.site||'','placeholder="sf.gov.kg" inputmode="url"'),{full:true,id:'vd-site',hint:'Открывается в новой вкладке'})}${fld('Сверить',inp('vd-cn',x&&x.contactsNote||'','placeholder="Например: с сайта органа 27.10.2026, сверить номер"'),{full:true,id:'vd-cn',hint:'Откуда взяты контакты и что ещё сверить; организации видят пометку «Сверить: …» под контактами. Пусто — контакты сверены'})}`;
function organCtBind(el){const tb=$('#vd-ct tbody',el),tw=tb.closest('.tbl-wrap'),sy=()=>{tw.hidden=!tb.rows.length};sy();
  $('#vd-cadd',el).onclick=()=>{tb.insertAdjacentHTML('beforeend',ctRow());sy();tb.rows[tb.rows.length-1].querySelector('[data-cl]').focus()};
  tb.onclick=e=>{const b=e.target.closest('[data-crm]');if(b){b.closest('tr').remove();sy();setErr(el,'vd-ct','')}}}
// Проверка и сбор контактов; null — есть ошибка (показана под полем)
function organCtRead(el){const ct=$$('#vd-ct tbody tr',el).map(tr=>({label:$('[data-cl]',tr).value.trim(),value:$('[data-cv]',tr).value.trim()})).filter(c=>c.label||c.value);
  let s=val(el,'vd-site');const se=s&&!/^(https?:\/\/)?[a-zа-яё0-9-]+(\.[a-zа-яё0-9-]+)+(\/\S*)?$/i.test(s)?'Адрес сайта, например sf.gov.kg':'';if(s&&!se&&!/^https?:\/\//i.test(s))s='https://'+s;
  const ce=ct.some(c=>!c.value)?'У каждой подписи нужен номер':ct.some(c=>!c.label)?'Подпишите каждый номер, например «Приёмная»':ct.some(c=>!/^\+?[\d\s()-]+$/.test(c.value)||c.value.replace(/\D/g,'').length<3)?'Номер — цифры, пробелы, скобки и «-», например 0 (312) 54-45-29':'';
  const ok=[setErr(el,'vd-ct',ce),setErr(el,'vd-site',se)].every(Boolean);return ok?{contacts:ct,hours:val(el,'vd-hours'),site:s,contactsNote:val(el,'vd-cn')}:null}
function valueDlg(k,x){const d=DICT[k];const nf=fld(k==='forms'?'Что меняет в налогах':k==='organs'?'Что это и что туда сдают':'Пояснение',`<textarea class="inp" id="vd-note" style="min-height:60px">${esc(x&&x.note||'')}</textarea>`,{full:true,id:'vd-note',hint:'Видят все организации в справочниках платформы'});const xf=k==='forms'?`${fld('Полное название',inp('vd-full',x&&x.full||''),{full:true,id:'vd-full'})}${fld('Кратко',inp('vd-short',x&&x.short||''),{id:'vd-short'})}${fld('Для ЕНД',sel('vd-end',Object.entries(END_L),x&&x.end||'org'),{id:'vd-end',hint:'Какой ЕНД назначается контрагенту с этой формой'})}`:k==='organs'?organCtHtml(x):k==='banks'?`${fld('Тип',sel('vd-type',BANK_T,x&&x.type||'Банк'),{id:'vd-type'})}<label class="check-row"><input type="checkbox" class="sw" id="vd-ph" ${x&&x.byPhone?'checked':''}><span class="grow">Переводы по номеру телефона<div class="hint">Провайдер предлагается в реквизите «Перевод по номеру телефона» у организаций и сотрудников</div></span></label>`:'';
  openModal({form:true,render:()=>({title:x?'Изменить':`Новое значение · ${esc(d.title)}`,body:`<div class="form">${fld('Название',inp('vd-n',x?x.name:''),{req:true,full:!!xf,id:'vd-n',hint:x?'Новое название увидят все организации, в том числе в старых записях':''})}${xf}${nf}</div>`,foot:'<button class="btn ghost" data-close>Отмена</button><button class="btn cta" id="vd-ok">Сохранить</button>',
  mount(el,m){if(k==='organs')organCtBind(el);$('#vd-ok',el).onclick=()=>{const n=val(el,'vd-n');if(!setErr(el,'vd-n',!n?'Введите название':d.items.some(i=>i.name===n&&i!==x)?'Такое значение уже есть':''))return;
    const oc=k==='organs'?organCtRead(el):{};if(!oc)return;
    const ex=Object.assign(k==='forms'?{full:val(el,'vd-full').trim(),short:val(el,'vd-short').trim(),end:val(el,'vd-end')}:k==='banks'?{type:val(el,'vd-type'),byPhone:$('#vd-ph',el).checked}:oc,{note:val(el,'vd-note').trim()});const chg=x?Object.keys(ex).filter(f=>f==='contacts'?JSON.stringify(ex[f])!==JSON.stringify(x[f]||[]):ex[f]!==(f==='byPhone'?!!x[f]:x[f]||'')):[];if(chg.length){Object.assign(x,ex);touch(x);if(x.name===n)pdLog(`${d.title}: «${n}» — изменены поля: ${chg.map(f=>VD_FL[f]||f).join(', ')}`)}
    if(x&&x.name!==n){const o=x.name;x.name=n;touch(x);if(k==='regimes'){CPS.forEach(c=>{if(c.regime===o)c.regime=n});RT.forEach(t=>{t.regimes=t.regimes.map(r=>r===o?n:r)})}if(k==='forms')CPS.forEach(c=>{if(c.form===o)c.form=n});if(k==='organs')RT.forEach(t=>{if(t.organ===o)t.organ=n});if(k==='cats')TASKS.forEach(t=>{if(t.cat===o)t.cat=n});if(k==='banks')rqRename(o,n);pdLog(`${d.title}: «${o}» → «${n}»`)}
    else if(!x){d.items.push(born(Object.assign({name:n,active:true,code:nextCode(k,k==='banks'&&ex.type==='Электронный кошелёк'?'КШЛ':DX[k].pre)},ex)));pdLog(`${d.title}: добавлено «${n}»`)}m.close();renderPage();toast('Сохранено')}}})})}
function ugnsDlg(x){openModal({form:true,render:()=>({title:x?'Налоговый орган':'Новый налоговый орган',sub:'Справочник платформы',body:`<div class="form">${fld('Код',inp('ug-code',x?x.code:'','class="inp mono" inputmode="numeric" maxlength="3" placeholder="002"'),{id:'ug-code',hint:'Три цифры, как в кабинете налогоплательщика; пусто — пока код не сверен с ГНС'})}${fld('Регион',inp('ug-city',x?x.city:'г. Бишкек'),{id:'ug-city'})}${fld('Полное название',inp('ug-name',x?x.name:'','placeholder="УГНС по Ленинскому району г. Бишкек"'),{req:true,full:true,id:'ug-name'})}${fld('Краткое название',inp('ug-short',x?x.short:'','placeholder="Ленинский р-н, Бишкек"'),{req:true,full:true,id:'ug-short',hint:'Показывается в списках рядом с кодом'})}</div>${x&&usedCount.ugns(ugK(x))?`<div class="note warn">${ic('alert')}<span>Управление указано у ${usedCount.ugns(ugK(x))} контрагентов. При смене кода он изменится и у них.</span></div>`:''}`,
  foot:'<button class="btn ghost" data-close>Отмена</button><button class="btn cta" id="ug-ok">Сохранить</button>',
  mount(el,m){$('#ug-ok',el).onclick=()=>{const code=val(el,'ug-code');const ok=[setErr(el,'ug-code',code&&!/^\d{3}$/.test(code)?'Ровно три цифры':code&&DICT.ugns.items.some(i=>i.code===code&&i!==x)?'Такой код уже есть':''),setErr(el,'ug-name',!val(el,'ug-name')?'Введите название':DICT.ugns.items.some(i=>i!==x&&norm(i.name)===norm(val(el,'ug-name')))?'Такое управление уже есть':''),setErr(el,'ug-short',val(el,'ug-short')?'':'Введите краткое название')].every(Boolean);if(!ok)return;
    const o={code,name:val(el,'ug-name'),short:val(el,'ug-short'),city:val(el,'ug-city')};if(!x)o.id='ugns-'+Date.now().toString(36);
    if(x){const k0=ugK(x),k1=code||x.id;if(k0!==k1)CPS.forEach(c=>{if(c.ugns===k0)c.ugns=k1});const was=`${x.code} · ${x.short} · ${x.name} · ${x.city}`;Object.assign(x,o);touch(x);pdLog(`УГНС: «${code} ${o.short}» изменено. Было: ${was}. Стало: ${code} · ${o.short} · ${o.name} · ${o.city}`)}else{DICT.ugns.items.push(born(Object.assign(o,{active:true})));pdLog(`УГНС: добавлено «${code} ${o.short}»`)}
    m.close();refreshAll();toast('Сохранено')}}})})}
